// PC 登録。新規購入も他部署からの搬入も同じ入口で扱う。
// 入力: {
//   acquisition: 'purchase'|'transfer', user_name, user_email, model, acquired_at,
//   purpose: 'dev'|'test'|'misc',
//   asset_no, asset_no_provisional, computer_name, computer_name_provisional,
//   ip?, installed?: ['jetbrains', ...]
// }
// 設計: docs/design/02-pc-register.md

const i = $input.first()?.json ?? {};
const need = ['user_email', 'model', 'acquired_at', 'asset_no', 'computer_name'];
const missing = need.filter((k) => !i[k]);
if (missing.length) throw new Error(`pc-register: 必須項目がありません: ${missing.join(', ')}`);

if (!['purchase', 'transfer'].includes(i.acquisition ?? 'purchase')) {
  throw new Error(`pc-register: acquisition は purchase か transfer です: ${i.acquisition}`);
}
// 資産管理番号は state のファイル名になるため、パスに使える形に限る
if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(String(i.asset_no))) {
  throw new Error(`pc-register: 資産管理番号に使えない文字が含まれます: ${i.asset_no}`);
}

return [{ json: {
  base: `${$env.NETBOX_URL}/api`,
  acquisition: i.acquisition ?? 'purchase',
  userName: i.user_name ?? '',
  userEmail: i.user_email,
  model: i.model,
  acquiredAt: i.acquired_at,
  purpose: i.purpose ?? 'dev',
  assetNo: String(i.asset_no),
  assetProvisional: i.asset_no_provisional === true,
  computerName: String(i.computer_name),
  nameProvisional: i.computer_name_provisional === true,
  ip: i.ip || null,
  installed: Array.isArray(i.installed) ? i.installed : [],
}}];

// 重複していたら自動リネームせず差し戻す(勝手に名前を変えない)。
const ctx = $('入力を検証する').first().json;
const byName = $('名前の重複を確認').first().json;
const byAsset = $input.first().json;

const dup = [];
if ((byName?.count ?? 0) > 0) dup.push(`コンピュータ名 '${ctx.computerName}'`);
if ((byAsset?.count ?? 0) > 0) dup.push(`資産管理番号 '${ctx.assetNo}'`);
if (dup.length) {
  throw new Error(`pc-register: 既に登録されています(${dup.join(' / ')})。値を確認して再申請してください`);
}

return [{ json: ctx }];

// 登録できなければ止める。呼び出し側(将来のフォーム)が
// 管理者へのエスカレーションと手動登録タスクに切り替える。
const ctx = $('重複を判定する').first().json;
const res = $input.first()?.json ?? {};
if (!res.id) {
  const detail = res.error?.message ?? JSON.stringify(res).slice(0, 200);
  throw new Error(`pc-register: NetBox への登録に失敗しました: ${detail}`);
}
return [{ json: { ...ctx, deviceId: res.id, kind: 'catalog' } }];

// 起票するタスクを組み立てて state/pcs/<資産管理番号>.yaml に書く入力を作る。
//   pc-license        必須ソフトの購入(導入済みのものは除く)
//   pc-official-info  仮の値を正式な値に置き換える(blocking)
//   pc-ip             IP の登録(blocking: false — 強制しないが漏れは追う)

const crypto = require('crypto');
const ctx = $('登録結果を確認').first().json;

const catalog = {};
for (const it of $input.all()) catalog[it.json.id] = it.json.desired;
const software = (catalog['pc-software']?.software ?? []).filter((s) => s.enabled !== false);

let ipResult = null;
try { ipResult = $('IPを割り当てる').first().json; } catch (e) { ipResult = null; }
const ipAssigned = ipResult?.ok === true;

const webhookBase = String($env.WEBHOOK_URL ?? 'http://localhost:5678/').replace(/\/$/, '');
const acquired = new Date(ctx.acquiredAt);
const iso = (d) => d.toISOString().slice(0, 10);
const due = (days) => { const d = new Date(acquired); d.setDate(d.getDate() + days); return iso(d); };

const tasks = [];
const mkTask = (t) => {
  const token = crypto.randomBytes(16).toString('hex');
  return { ...t, status: 'open', remind_count: 0, last_reminded_at: null, token,
    created_at: new Date().toISOString(),
    complete_url: `${webhookBase}/webhook/task-complete?kind=pcs`
      + `&member=${encodeURIComponent(ctx.assetNo)}&task=${encodeURIComponent(t.id)}&token=${token}` };
};

for (const s of software) {
  if (ctx.installed.includes(s.id)) continue;   // 搬入 PC などで導入済み
  tasks.push(mkTask({
    id: `pc-license:${s.id}`,
    kind: 'pc-license',
    subject: `${ctx.computerName} / ${ctx.userName || ctx.userEmail} 向けに ${s.name} を購入する`,
    steps: s.vendor_url ? `購入先: ${s.vendor_url}` : '',
    assignee: $env[s.assignee] || s.assignee || $env.ADMIN_EMAILS,
    due: due(Number(s.due_days ?? 7)),
    verify: s.verify ?? 'human',
    blocking: true,
  }));
}

if (ctx.assetProvisional || ctx.nameProvisional) {
  const which = [ctx.assetProvisional ? '資産管理番号' : null, ctx.nameProvisional ? 'コンピュータ名' : null]
    .filter(Boolean).join(' と ');
  tasks.push(mkTask({
    id: 'pc-official-info',
    kind: 'pc-official-info',
    subject: `${ctx.computerName}: 正式な${which}を反映する`,
    steps: '情シスの採番後、機器情報更新フォームか NetBox で更新してください',
    assignee: $env.ADMIN_EMAILS,
    due: due(14),   // 情シスの採番リードタイムを考慮して緩め
    verify: 'api',
    blocking: true,
  }));
}

if (!ipAssigned) {
  tasks.push(mkTask({
    id: 'pc-ip',
    kind: 'pc-ip',
    subject: `${ctx.computerName}: IP アドレスを登録する`,
    steps: 'キッティング後、機器情報更新フォームか NetBox で登録してください',
    assignee: ctx.userEmail,
    due: null,          // 期限なし。リマインド間隔だけで追いかける
    verify: 'api',
    blocking: false,    // 未登録でも active を妨げない
  }));
}

const blocking = tasks.filter((t) => t.blocking).length;

return [{ json: {
  kind: 'pcs',
  id: ctx.assetNo,
  patch: {
    netbox_device_id: ctx.deviceId,
    user: ctx.userEmail,
    acquisition: ctx.acquisition,
    acquired_at: ctx.acquiredAt,
    computer_name: { value: ctx.computerName, provisional: ctx.nameProvisional },
    asset_no: { value: ctx.assetNo, provisional: ctx.assetProvisional },
    ip_address: ipAssigned ? ipResult.ip : null,
    status: blocking > 0 ? 'license-pending' : 'active',
    tasks,
    updated_at: new Date().toISOString(),
  },
  reason: `PC 登録(${ctx.acquisition === 'transfer' ? '搬入' : '新規購入'})`,
  __summary: {
    assetNo: ctx.assetNo, computerName: ctx.computerName, deviceId: ctx.deviceId,
    ip: ipAssigned ? ipResult.ip : null, tasks: tasks.map((t) => t.subject),
  },
}}];

const s = $('タスクを組み立てる').first().json.__summary;
const write = $input.first()?.json ?? {};
return [{ json: {
  ok: write.ok === true,
  asset_no: s.assetNo,
  computer_name: s.computerName,
  netbox_device_id: s.deviceId,
  netbox_url: `${String($env.NETBOX_URL).replace('netbox:8080', 'localhost:8000')}/dcim/devices/${s.deviceId}/`,
  ip: s.ip,
  tasks: s.tasks,
  ledger: write.path ?? null,
}}];
